fn checked(n: Int) -> Result[Int, String] {
    if n >= 0 { Ok(n) } else { Err("negative") }
}

fn run(n: Int) -> Result[Int, Int] {
    let v = checked(n)?    // ✗ propagates a `String` error, but `run` returns `Int` errors
    Ok(v + 1)
}

fn run(n: Int) -> Result[Int, Int] {
    let v = checked(n).mapErr((e) => e.length())?    // ✓ the error is converted first
    Ok(v + 1)
}
